using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class CoverageDecorationReceiptTests
{
    private const string Source = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int Value { get; set; }

            [Key(1)]
            public MyEnum EnumValue { get; set; }
        }

        [MessagePackObject(true)]
        public class StringKeyedObject
        {
            public string Name { get; set; }
        }

        public enum MyEnum
        {
            None,
            Value,
        }

        [GeneratedMessagePackResolver]
        public partial class TestResolver
        {
        }
        """;

    [Fact]
    public async Task AllGeneratedTypesAreDecoratedWithoutAnySetting()
    {
        (ImmutableArray<SyntaxTree> generatedTrees, CSharpCompilation compilation) = await GenerateAsync(Array.Empty<string>());

        generatedTrees.Should().NotBeEmpty();
        compilation.GetDiagnostics().Where(diagnostic => diagnostic.Severity == DiagnosticSeverity.Error).Should().BeEmpty();

        foreach (SyntaxTree tree in generatedTrees)
        {
            ClassDeclarationSyntax[] generatedClasses = tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>().ToArray();
            generatedClasses.Should().NotBeEmpty("every generated source file should contain its generated type");
            generatedClasses.Should().OnlyContain(
                type => HasCoverageAttribute(type),
                "every generated class, including resolvers and nested helpers, should be excluded from code coverage by default");
        }
    }

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task GeneratedCodeCompilesWhenCoverageAttributeIsConditionallyOmitted(string targetSymbol)
    {
        (ImmutableArray<SyntaxTree> generatedTrees, CSharpCompilation compilation) = await GenerateAsync(new[] { targetSymbol });

        generatedTrees.Should().NotBeEmpty();
        compilation.GetDiagnostics().Where(diagnostic => diagnostic.Severity == DiagnosticSeverity.Error).Should().BeEmpty();
    }

    private static bool HasCoverageAttribute(ClassDeclarationSyntax declaration)
    {
        return declaration.AttributeLists
            .SelectMany(list => list.Attributes)
            .Any(attribute => attribute.Name.ToString() == "global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage");
    }

    private static async Task<(ImmutableArray<SyntaxTree> GeneratedTrees, CSharpCompilation Compilation)> GenerateAsync(IEnumerable<string> preprocessorSymbols)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3, preprocessorSymbols: preprocessorSymbols);
        SyntaxTree sourceTree = CSharpSyntaxTree.ParseText(Source, parseOptions);
        ImmutableArray<MetadataReference> references = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        references = references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        var compilation = CSharpCompilation.Create(
            "CoverageDecorationReceipt",
            new[] { sourceTree },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator(),
            parseOptions: parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation outputCompilation, out _, CancellationToken.None);

        return (driver.GetRunResult().GeneratedTrees, (CSharpCompilation)outputCompilation);
    }
}
